// Stage-local process observation only. It does not intercept HTTP or test APIs.
const fs = require('node:fs')
const childProcess = require('node:child_process')
const { syncBuiltinESMExports } = require('node:module')
const { promisify } = require('node:util')
const registry = process.env.ORBIT_PROCESS_REGISTRY
if (registry) {
  const realNow = Date.now.bind(Date)
  const record = value => fs.appendFileSync(registry, `${JSON.stringify({ ...value, at: realNow() })}\n`)
  const registered = new WeakSet()
  const register = child => {
    if (child?.pid && !registered.has(child)) {
      registered.add(child)
      record({ event: 'spawn', pid: child.pid, ppid: process.pid, argv: child.spawnargs })
      child.once('exit', (code, signal) => record({ event: 'exit', pid: child.pid, ppid: process.pid, code, signal }))
    }
    return child
  }
  for (const name of ['spawn', 'fork', 'exec', 'execFile']) {
    const original = childProcess[name]
    const wrapped = function (...args) {
      const child = Reflect.apply(original, this, args)
      return register(child)
    }
    const descriptors = Object.getOwnPropertyDescriptors(original)
    if (original[promisify.custom]) descriptors[promisify.custom] = {
      ...descriptors[promisify.custom],
      value: function (...args) {
        const result = Reflect.apply(original[promisify.custom], this, args)
        register(result.child)
        return result
      },
    }
    Object.defineProperties(wrapped, descriptors)
    childProcess[name] = wrapped
  }
  syncBuiltinESMExports()
  record({ event: 'observer-start', pid: process.pid, ppid: process.ppid })
}

