"""Observe registered children and descendants; never signal an unowned PID."""
from datetime import datetime, timezone
from pathlib import Path
import json
import os
import signal
import subprocess
import time


def snapshot():
    environment = {**os.environ, "TZ": "UTC", "LC_ALL": "C"}
    output = subprocess.check_output(
        ["ps", "-axo", "pid=,ppid=,pgid=,lstart=,command="], text=True, env=environment,
    )
    processes = {}
    for line in output.splitlines():
        parts = line.strip().split(None, 8)
        if len(parts) != 9:
            continue
        started = " ".join(parts[3:8])
        processes[int(parts[0])] = {
            "pid": int(parts[0]), "ppid": int(parts[1]), "pgid": int(parts[2]),
            "started": started, "command": parts[8],
            "startedEpoch": datetime.strptime(started, "%a %b %d %H:%M:%S %Y").replace(tzinfo=timezone.utc).timestamp(),
        }
    return processes


def same_process(left, right):
    # Node may change its process title after launch; that is not a new process.
    return left["pid"] == right["pid"] and left["started"] == right["started"] and left["pgid"] == right["pgid"]


class Ownership:
    def __init__(self, root_pid, registry=None):
        self.root_pid = root_pid
        self.registry = Path(registry) if registry else None
        self.owned = {}
        self.groups = {root_pid}
        self.registrations = {}
        self.observers = {}
        self.lifetimes = set()
        self.registry_errors = []
        self.pending_tail = False
        self.initial = True
        self.update()

    def update(self):
        current = snapshot()
        if not self.initial:
            self.groups.intersection_update({
                process["pgid"] for pid, process in current.items()
                if pid in self.owned and same_process(self.owned[pid], process)
            })
        if self.registry and self.registry.exists():
            contents = self.registry.read_text()
            self.pending_tail = bool(contents and not contents.endswith("\n"))
            lines = contents.splitlines()
            if self.pending_tail:
                lines = lines[:-1]
            for number, line in enumerate(lines):
                try:
                    event = json.loads(line)
                    if event.get("event") == "spawn":
                        self.registrations[(event["pid"], event["at"])] = event
                    elif event.get("event") == "observer-start":
                        self.observers[(event["pid"], event["at"])] = event
                except (ValueError, KeyError, TypeError) as error:
                    item = {"line": number + 1, "error": str(error)}
                    if item not in self.registry_errors:
                        self.registry_errors.append(item)
        for event in self.registrations.values():
            process = current.get(event["pid"])
